const s = $json;
const NL = String.fromCharCode(10);
const idea = s.idea;
const label = s.cfg.context_label || 'Matemáticas de Grado Superior de la Comunidad Valenciana';
const system = 'Eres guionista de microvídeos educativos de AccesoPro, que prepara a personas adultas para las pruebas de acceso (' + label + '). Escribes en español de España, con tono cercano, claro y motivador, tuteando al alumno. REGLAS: 1) Usa SOLO contenido y cifras del temario o del material de fuente que te doy; si no hay material de fuente, usa únicamente matemáticas estándar dentro del alcance del tema. No inventes datos, normas, estadísticas ni ejemplos que no puedas comprobar. 2) Cada operación matemática que escribas debe ser correcta: calcúlala paso a paso antes de escribirla y usa ejemplos sencillos. 3) El texto se leerá en voz alta: escribe todo como se pronuncia (por ejemplo "cinco sextos", "dos elevado a menos tres", "equis"), sin símbolos matemáticos, sin markdown y sin emojis. 4) Estructura: GANCHO (1-2 frases, máximo 8 segundos, abre con un error típico, una pregunta o una promesa concreta), EXPLICACIÓN (clara y ordenada, con un solo ejemplo numérico), CIERRE (1 frase con llamada a la acción: practica este tema con los cursos de AccesoPro y sigue el canal). 5) DURACIÓN ESTRICTA: el vídeo debe durar entre 35 y 55 segundos al ritmo de lectura, es decir, entre 85 y 115 palabras EN TOTAL (gancho, explicación y cierre juntos). Nunca superes las 115 palabras: cuenta las palabras antes de entregar y recorta si hace falta. 6) Centra el vídeo únicamente en la idea que te asigno; no repitas ejemplos de otras ideas.';
const fuente = s.ctx.podcast ? 'FUENTE ELABORADA (material de apoyo del mismo tema):' + NL + s.ctx.podcast + NL + NL : '';
const user = 'TEMARIO ACCESOPRO DEL TEMA:' + NL + s.ctx.temario + NL + NL + fuente + 'IDEA A DESARROLLAR: ' + idea.titulo + NL + 'Apartado del temario: ' + (idea.apartado_temario || '') + NL + 'Puntos clave: ' + (idea.puntos_clave || []).join('; ') + NL + 'Error típico a destacar: ' + (idea.error_tipico || 'ninguno') + NL + NL + 'Entrega el guion con la herramienta.';
const tool = {
  name: 'entregar_guion',
  description: 'Entrega el guion final del vídeo dividido en gancho, explicación y cierre',
  input_schema: {
    type: 'object',
    properties: {
      gancho: { type: 'string', description: 'Gancho inicial, 1-2 frases' },
      explicacion: { type: 'string', description: 'Explicación con ejemplo numérico correcto' },
      cierre: { type: 'string', description: 'Cierre con llamada a la acción' }
    },
    required: ['gancho', 'explicacion', 'cierre']
  }
};
const req = { model: s.cfg.writer_model, max_tokens: 1500, temperature: 0.4, system: system, messages: [{ role: 'user', content: user }], tools: [tool], tool_choice: { type: 'tool', name: 'entregar_guion' } };
return { json: Object.assign({}, s, { req: req, costs: s.costs || { llm: 0, voice: 0, stt: 0 }, attempts: s.attempts || 0 }) };

const s = $('Prompt guion').item.json;
const r = $json;
const block = (r.content || []).find((b) => b.type === 'tool_use');
if (!block) throw new Error('Claude no devolvió el guion');
const g = block.input;
const u = r.usage || {};
const cost = ((u.input_tokens || 0) * s.cfg.price_writer_in + (u.output_tokens || 0) * s.cfg.price_writer_out) / 1000000;
const out = Object.assign({}, s);
delete out.req;
out.script = { gancho: g.gancho, explicacion: g.explicacion, cierre: g.cierre };
out.text = [g.gancho, g.explicacion, g.cierre].join(' ');
out.word_count = out.text.split(' ').length;
out.costs = { llm: (s.costs.llm || 0) + cost, voice: s.costs.voice || 0, stt: s.costs.stt || 0 };
return { json: out };

const s = $json;
const NL = String.fromCharCode(10);
const label = s.cfg.context_label || 'Matemáticas de Grado Superior de la Comunidad Valenciana';
const system = 'Eres guionista de microvídeos educativos de AccesoPro (preparación de pruebas de acceso para adultos, ' + label + '). Un agente revisor ha RECHAZADO tu guion. Corrige exactamente los problemas señalados: recalcula cada operación, elimina o sustituye cualquier dato no respaldado por el temario, y mantén gancho, explicación y cierre, el tono cercano, el texto pronunciable (sin símbolos matemáticos) y una duración ESTRICTA de entre 85 y 115 palabras en total (nunca más de 115). No añadas contenido nuevo que no puedas respaldar.';
const user = 'TEMARIO OFICIAL:' + NL + s.ctx.official + NL + NL + 'TEMARIO ACCESOPRO DEL TEMA:' + NL + s.ctx.temario + NL + NL + 'GUION RECHAZADO:' + NL + 'GANCHO: ' + s.script.gancho + NL + 'EXPLICACIÓN: ' + s.script.explicacion + NL + 'CIERRE: ' + s.script.cierre + NL + NL + 'INFORME DEL REVISOR:' + NL + s.review_reason + NL + NL + 'Entrega el guion corregido con la herramienta.';
const tool = {
  name: 'entregar_guion',
  description: 'Entrega el guion corregido dividido en gancho, explicación y cierre',
  input_schema: {
    type: 'object',
    properties: { gancho: { type: 'string' }, explicacion: { type: 'string' }, cierre: { type: 'string' } },
    required: ['gancho', 'explicacion', 'cierre']
  }
};
const req = { model: s.cfg.writer_model, max_tokens: 1500, temperature: 0.2, system: system, messages: [{ role: 'user', content: user }], tools: [tool], tool_choice: { type: 'tool', name: 'entregar_guion' } };
return { json: Object.assign({}, s, { req: req, attempts: (s.attempts || 0) + 1, script_rechazado: s.script }) };

const s = $('Prompt corrección').item.json;
const r = $json;
const block = (r.content || []).find((b) => b.type === 'tool_use');
if (!block) throw new Error('Claude no devolvió el guion corregido');
const g = block.input;
const u = r.usage || {};
const cost = ((u.input_tokens || 0) * s.cfg.price_writer_in + (u.output_tokens || 0) * s.cfg.price_writer_out) / 1000000;
const out = Object.assign({}, s);
delete out.req;
out.script = { gancho: g.gancho, explicacion: g.explicacion, cierre: g.cierre };
out.text = [g.gancho, g.explicacion, g.cierre].join(' ');
out.word_count = out.text.split(' ').length;
out.costs = { llm: (s.costs.llm || 0) + cost, voice: s.costs.voice || 0, stt: s.costs.stt || 0 };
